package com.stockflow.inventory;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="inventory_movement") @Getter @NoArgsConstructor public class InventoryMovement { @Id private UUID id; @Column(name="company_id",nullable=false) private UUID companyId; @Enumerated(EnumType.STRING) @Column(nullable=false) private MovementType type; @Column(name="reference_type",nullable=false) private String referenceType; @Column(name="reference_id",nullable=false) private UUID referenceId; @Column(nullable=false) private Instant postedAt; @Column(name="actor_id",nullable=false) private UUID actorId; private UUID reversesMovementId; public InventoryMovement(UUID c,MovementType t,String rt,UUID r,UUID actor){id=UUID.randomUUID();companyId=c;type=t;referenceType=rt;referenceId=r;actorId=actor;postedAt=Instant.now();}}
